BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·乾祐三年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/197cc3dbf958eccdbfaf129b605c39322b104431/content/books/zizhi-tongjian/vol-289/year-0950/part-06/sources/library/jiuwudaishi-103-november-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年十一月，段落 jiu-wudaishi-205deb4a7860-p002494；已核上下文及传主，纸本及异文待核。", "id": "2c328b83-7f54-5ad7-a5d0-94c2ddc5e2b2"}, {"title": "旧五代史·卷124·王殷传·籍贯与驻澶州", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/197cc3dbf958eccdbfaf129b605c39322b104431/content/books/zizhi-tongjian/vol-289/year-0950/part-06/sources/library/jiuwudaishi-124-wang-yin-origin/source.txt", "note": "《旧五代史》卷124·王殷传·籍贯与驻澶州，段落 jiu-wudaishi-205deb4a7860-p002878；已核上下文及传主，纸本及异文待核。", "id": "ca713a48-8090-50aa-aa37-d170f37112db"}, {"title": "资治通鉴·卷289·乾祐三年·十月至十一月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/197cc3dbf958eccdbfaf129b605c39322b104431/content/books/zizhi-tongjian/vol-289/year-0950/part-06/sources/library/tongjian-289-950-november-start/source.txt", "note": "《资治通鉴》卷289·乾祐三年·十月至十一月，段落 zizhi-tongjian-a63549944a71-p003430；已核上下文及传主，纸本及异文待核。", "id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"title": "资治通鉴·卷289·乾祐三年·闰月与六月等", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/tongjian-289-950-intercalary-month/source.txt", "note": "《资治通鉴》卷289·乾祐三年·闰月与六月等，段落 zizhi-tongjian-a63549944a71-p003429；已核上下文及传主，纸本及异文待核。", "id": "34e5229e-bf1a-5a50-b15a-3287f46ac4fa"}, {"title": "新五代史·卷66·楚世家·仆射洲之战及后续", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/xinwudaishi-066-pushezhou/source.txt", "note": "《新五代史》卷66·楚世家·仆射洲之战及后续，段落 xin-wudaishi-b08f244b9241-p003329；已核上下文及传主，纸本及异文待核。", "id": "1de76302-3d97-5251-886d-6cba3e293c85"}, {"title": "新五代史·卷62·南唐世家·陈诲后续活动校核", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-062-chen-hui-later/source.txt", "note": "《新五代史》卷62·南唐世家·八年陈诲参战，段落 xin-wudaishi-b08f244b9241-p003145；仅作946年死亡记载的时序异说校核，不提前录入后续战事；纸本及异文待核。", "id": "a90839a2-9053-5777-b22f-e70b09603b35"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "张晖（马希广将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的马军指挥使。950年从另一条路线攻朗州，得知刘彦瑫战败后驻益阳；遭进攻时骗部下留城，自己逃回长沙。与博州守将、后晋使者等同名人物尚无同人证据，分开建档。生卒年未载。", "biography": null, "status": "draft", "id": "01326810-19e9-5e02-8181-27a823949592"}, {"name": "朱进忠", "aliases": ["硃进忠", "朱進忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的指挥使。950年率兵三千攻益阳，随后建议马希萼亲自率军攻潭州。电子底本也写硃进忠，统一简体姓名，原文保留。生卒年未载。", "biography": null, "status": "draft", "id": "0ba585e1-d1aa-5ce5-ad37-d02d89127713"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "赵廷隐", "aliases": ["趙廷隱"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：赵廷隐。", "biography": null, "status": "draft", "id": "bc139832-e17d-51c1-b2c5-a6b9fcca1a14"}, {"name": "孟骈", "aliases": ["孟駢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的僚属。950年奉命劝马希萼不要向南唐称臣，遭到处死威胁，申说两军交战仍应允许使者往来后获释。生卒年未载。", "biography": null, "status": "draft", "id": "7d833f16-e55e-5112-9fb6-2fbbdbb85066"}, {"name": "马光赞", "aliases": ["馬光贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的儿子。950年十一月，马希萼率军向长沙进发，留下他守朗州。生卒年和母亲身份未载。", "biography": null, "status": "draft", "id": "3fbbf096-7e41-591f-8fb9-2c5b3cb24eb3"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "刘彦瑫请求率水陆军直攻朗州", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，具体进言日未载", "dynasty": "五代十国", "description": "刘彦瑫向马希广声称朗州兵力不足，楚国都府兵力占优，请给他万余兵和一百五十艘战舰，直攻朗州、擒取马希萼。", "phases": [], "location_name": "楚国朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "15977e3e-950f-5b9a-8ba0-e5df2d9f3c53"}, {"title": "马希广任命刘彦瑫统率攻朗州的军队", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，进言之后，具体任命日未载", "dynasty": "五代十国", "description": "马希广任命刘彦瑫统率攻朗州的军队。", "phases": [], "location_name": "楚国朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9c648c51-6fcd-5d07-84a8-345f711f72ff"}, {"title": "朗州父老犒劳刘彦瑫军队，随后用竹木断其归路", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，刘彦瑫进军朗州时，具体日未载", "dynasty": "五代十国", "description": "朗州父老带牛酒犒军，声称盼望都府军队已久，刘彦瑫重赏他们。战舰经过后，史书记这些父老运竹木截断军队后路。", "phases": [], "location_name": "朗州境内水路", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "57ec4875-3819-5cd9-ad6d-a5eeeab0467f"}, {"title": "马希萼派六千兵与百艘战舰在湄州迎战", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，刘彦瑫进军当天，具体日期未载", "dynasty": "五代十国", "description": "马希萼派六千兵与百艘战舰在湄州迎战。", "phases": [], "location_name": "湄州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d773c0ce-ebcc-5da9-b5bd-8add7138fa1b"}, {"title": "刘彦瑫在湄州火攻遇风向改变，败退时归路被断", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，湄州交战当天，具体日期未载", "dynasty": "五代十国", "description": "刘彦瑫顺风放火烧敌方战舰，风向很快改变，火反烧己方。他退军时江路已经被截断，史书称数千士卒战死或溺死。", "phases": [], "location_name": "湄州及退军水路", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c907c32e-1967-5d12-a7fe-3ab7c95d6b99"}, {"title": "马希广得知战败后哭泣，大量赏赐金帛给士卒", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，湄州败讯传到以后，具体日未载", "dynasty": "五代十国", "description": "马希广得知战败后哭泣，大量赏赐金帛给士卒。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1fe45370-5fbe-570f-a690-eb321af62bb4"}, {"title": "有人告马希崇煽动谋反，马希广拒绝杀弟", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，具体指控与答复日未载", "dynasty": "五代十国", "description": "有人向马希广指控天策左司马马希崇散布流言、谋反迹象明显，请求杀他。马希广说自己若害死弟弟，无法面对已故父亲，因此拒绝。", "phases": [], "location_name": "楚国朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "66c25f0a-69d4-541a-b003-1e40c242e72e"}, {"title": "张晖从另一条路攻朗州，闻刘彦瑫战败后退守益阳", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，湄州战败后，具体日未载", "dynasty": "五代十国", "description": "张晖从另一条路攻朗州，闻刘彦瑫战败后退守益阳。", "phases": [], "location_name": "龙阳、益阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e46d3c79-9e03-57e9-bf5d-6e4cd1bcf10e"}, {"title": "马希萼派朱进忠等率三千兵急攻益阳", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，张晖退屯益阳后，具体日未载", "dynasty": "五代十国", "description": "马希萼派朱进忠等率三千兵急攻益阳。", "phases": [], "location_name": "益阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a2d6564c-8424-5c84-b945-01473258ea39"}, {"title": "张晖谎称出城夹击敌军，实际逃回长沙", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，益阳遭攻时，具体日未载", "dynasty": "五代十国", "description": "张晖谎称出城夹击敌军，实际逃回长沙。", "phases": [], "location_name": "益阳、竹头市、长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4a763b87-3afa-5678-85ea-fe8bd5346395"}, {"title": "朗州军攻破无人主事的益阳，史书称九千余士卒死亡", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，张晖逃离之后，具体日未载", "dynasty": "五代十国", "description": "朗州军攻破无人主事的益阳，史书称九千余士卒死亡。", "phases": [], "location_name": "益阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6b1c7063-8f8c-5492-a769-1bf0a3e8b8b9"}, {"title": "钱弘俶将查文徽献于祖庙后释放", "start_year": 950, "end_year": 950, "time_original": "950年福州战事及送至钱唐之后，具体释放日未载", "dynasty": "五代十国", "description": "钱弘俶将查文徽献于祖庙后释放。", "phases": [], "location_name": "钱唐、吴越五庙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f24c2aef-b291-5067-be7f-d8bf748be0be"}, {"title": "查文徽患失语病，以工部尚书身份退休", "start_year": 950, "end_year": 950, "time_original": "950年十月条下，归南唐后，具体患病与退休日未载", "dynasty": "五代十国", "description": "查文徽患失语病，以工部尚书身份退休。", "phases": [], "location_name": "南唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8b385789-166e-5de4-b6b1-f596365de317"}, {"title": "史书记950年十一月甲子朔发生日食", "start_year": 950, "end_year": 950, "time_original": "950年十一月甲子朔", "dynasty": "五代十国", "description": "史书记9